<script setup lang="ts">
import { Building2, CheckCircle2, FileText, Landmark } from 'lucide-vue-next'
import { payslipTotals, type EmployeePayslip } from '~/utils/employeePayslip'

const props = defineProps<{ slip: EmployeePayslip; employee: { name: string; employeeId: string; position: string; department: string; location: string } }>()
const totals = computed(() => payslipTotals(props.slip))
const money = (amount: number) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(amount)
const groups = computed(() => [
  { title: 'Earnings & Allowances', rows: props.slip.earnings, empty: 'No earnings this period', total: totals.value.gross },
  { title: 'Benefits / Contributions', rows: props.slip.benefits, empty: 'No contributions this period', total: totals.value.benefits },
  { title: 'Other Deductions', rows: props.slip.deductions, empty: 'No other deductions this period', total: totals.value.deductions },
  { title: 'Loans', rows: props.slip.loans, empty: 'No loans', total: totals.value.loans },
])
</script>

<template>
  <section class="payroll-breakdown" aria-label="Detailed payslip breakdown">
    <div class="document-heading"><div class="document-brand"><span class="company-mark"><Building2 :size="22" /></span><div><strong>RWorkCentral Inc.</strong><span>Employee payslip · {{ slip.id }}</span></div></div><span class="release-badge"><CheckCircle2 :size="14" />Released</span></div>
    <header class="payroll-identity"><div class="employee-identity"><span class="field-label">Employee</span><h3>{{ employee.name }}</h3><span class="employee-id">{{ employee.employeeId }}</span><p>{{ employee.position }}</p><p>{{ employee.department }} · {{ employee.location }}</p></div><div class="payroll-bank"><span class="bank-symbol" aria-hidden="true"><Landmark :size="21" /></span><div><span class="field-label">Bank Information</span><p class="bank-name">{{ slip.bankName || 'Not provided' }}</p><strong class="bank-account">{{ slip.bankAccountNumber || 'Not provided' }}</strong><span class="bank-account-label">Account number</span></div></div></header>
    <dl class="payroll-meta"><div><dt>Pay Period</dt><dd>{{ slip.period }}</dd></div><div><dt>Payroll Scope</dt><dd>{{ slip.payrollScope }}</dd></div><div><dt>Batch / Reference</dt><dd>{{ slip.batch }}</dd></div><div><dt>Released</dt><dd>{{ slip.releasedAt }}</dd></div></dl>
    <dl class="payroll-metrics"><div><dt>Worked</dt><dd>{{ slip.daysWorked }} <small>days</small></dd></div><div><dt>Daily Rate</dt><dd>{{ money(slip.dailyRate) }}</dd></div><div class="gross-metric"><dt>Gross Earnings</dt><dd>{{ money(totals.gross) }}</dd></div><div class="deduction-metric"><dt>Total Deductions</dt><dd>{{ money(totals.totalDeductions) }}</dd></div><div class="net-metric"><dt>Net Pay</dt><dd>{{ money(totals.net) }}</dd></div></dl>
    <div class="breakdown-title"><h4>Pay breakdown</h4><span>All amounts in PHP</span></div>
    <div class="payroll-groups"><section v-for="(group, index) in groups" :key="group.title" class="group-card" :class="`group-${index}`"><h4>{{ group.title }}</h4><dl><div v-for="row in group.rows" :key="row.label"><dt>{{ row.label }}</dt><dd>{{ money(row.amount) }}</dd></div></dl><p v-if="!group.rows.length" class="empty-group">{{ group.empty }}</p><div class="group-total"><span>Total</span><strong>{{ money(group.total) }}</strong></div></section></div>
    <div class="payroll-remarks"><FileText :size="17" aria-hidden="true" /><div><strong>Remarks</strong><p>{{ slip.remarks }}</p></div></div>
    <p class="payroll-source">Benefits shown above are employee contributions included in Total Deductions. Figures are fictional frontend values, not verified payroll or statutory contribution calculations. This document includes your full bank account number; keep it private.</p>
  </section>
</template>

